const FIELDS = RESP.fields;
const ROWS = RESP.rows;
const FIDX = {}; FIELDS.forEach((f,i) => FIDX[f]=i);
function val(row, field) { return row[FIDX[field]]; }

// ---------------- FILTER DEFINITIONS ----------------
const FILTER_DEFS = [
  { key:'country', label:'Country', type:'multi', exclusiveTotal:true, options:['AU','CA','CN','FR','IN','KR','SG','UK','US'],
    names:{AU:'Australia',CA:'Canada',CN:'China',FR:'France',IN:'India',KR:'S. Korea',SG:'Singapore',UK:'UK',US:'US'} },
  { key:'age', label:'Age', type:'multi', options:['18-24','25-34','35-44','45-54'] },
  { key:'gender', label:'Gender', type:'multi', options:['M','F'], names:{M:'Male',F:'Female'} },
  { key:'income', label:'Income (within market)', type:'multi', options:['L','M','H'], names:{L:'Lower',M:'Middle',H:'Higher'} },
  { key:'conn', label:'Personal connection to Vietnam', type:'tri' },
  { key:'origin', label:'Vietnam origin (born/family)', type:'tri' },
  { key:'infl', label:'Influencer profile (F1)', type:'tri' },
  { key:'vaware', label:'Aware of Vietnam Today', type:'tri' },
  { key:'vviewer', label:'Has watched Vietnam Today', type:'tri' },
];

function defaultFilterState() {
  const st = {};
  FILTER_DEFS.forEach(f => { st[f.key] = f.type==='multi' ? [] : 'any'; });
  return st;
}
let filterA = defaultFilterState();
let filterB = defaultFilterState();
let compareOn = false;
let screenerTargetA = { country: 'TOTAL', base: 'all' };
let screenerTargetB = { country: 'CN', base: 'completes' };
let screenerCompareOn = false;
let topicsCompareCountry = 'Japan';
let a2Country = 'All';
const TOPCOUNTRY_OPTIONS = ['Japan','Thailand','Mexico','Poland','India','Indonesia','Kenya'];
const TOPIC_PAIRS = [
  ['food','Food & cuisine'],['travel','Travel & places'],['history','History & heritage'],['arts','Arts & entertainment'],
  ['business','Business & economy'],['tech','Technology & innovation'],['politics','Politics & current affairs'],
  ['lifestyle','Lifestyle & people'],['wellness','Wellness & spirituality'],['language','Language'],
];

function matchRow(row, state) {
  for (const f of FILTER_DEFS) {
    const sel = state[f.key];
    if (f.type === 'multi') {
      if (sel.length === 0) continue;
      if (!sel.includes(val(row, f.key))) return false;
    } else {
      if (sel === 'any') continue;
      const want = sel === 'yes' ? 1 : 0;
      if (val(row, f.key) !== want) return false;
    }
  }
  return true;
}

function filteredRows(state) { return ROWS.filter(r => matchRow(r, state)); }

