let currentSection = 'overview';
let currentModule = 'kpis';

// ---------------- AGGREGATION ----------------
function pctFlag(rows, field) {
  let n=0, hit=0;
  rows.forEach(r => { const v = val(r,field); if (v===1||v===0) { n++; if (v===1) hit++; } });
  return n>0 ? Math.round(hit/n*1000)/10 : null;
}
function catDist(rows, field) {
  let n=0; const counts = {};
  rows.forEach(r => { const v = val(r,field); if (v!==null && v!==undefined) { n++; counts[v]=(counts[v]||0)+1; } });
  const out = {};
  Object.keys(counts).forEach(k => out[k] = Math.round(counts[k]/n*1000)/10);
  return { dist: out, n };
}

// ---------------- DEMOGRAPHIC DRILLDOWN ----------------
let drilldownState = null; // { subRows, universeRows, label }

function clearDrilldown() {
  drilldownState = null;
  const el = document.getElementById('drilldownArea');
  if (el) el.innerHTML = '';
}

function showDrilldown(subRows, universeRows, label) {
  drilldownState = { subRows, universeRows, label };
  renderDrilldownPanel();
  const el = document.getElementById('drilldownArea');
  if (el && el.scrollIntoView) el.scrollIntoView({ behavior:'smooth', block:'nearest' });
}

const DRILL_COUNTRY_NAMES = { AU:'Australia', CA:'Canada', CN:'China', FR:'France', IN:'India', KR:'South Korea', SG:'Singapore', UK:'United Kingdom', US:'United States' };
const DRILL_GENDER_NAMES = { M:'Male', F:'Female', O:'Other / prefer not to say' };
const DRILL_INCOME_NAMES = { L:'Lower income', M:'Middle income', H:'Higher income' };

function drillCatRow(label, subDist, univDist, cat, nameMap) {
  const subV = subDist.dist[cat] || 0;
  const univV = univDist.dist[cat] || 0;
  const max = 100;
  const row = document.createElement('div'); row.className = 'barrow';
  row.innerHTML = `<div class="barlabel">${(nameMap && nameMap[cat]) || cat}</div>
    <div class="bartrack">
      <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:var(--drill);width:${subV}%"></div>
      <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:var(--text-muted);width:${univV}%"></div>
    </div>
    <div class="barval">${subV.toFixed(0)}% / ${univV.toFixed(0)}%</div>`;
  return row;
}

function drillFlagRow(label, subRows, univRows, field) {
  const subV = pctFlag(subRows, field);
  const univV = pctFlag(univRows, field);
  const row = document.createElement('div'); row.className = 'barrow';
  row.innerHTML = `<div class="barlabel">${label}</div>
    <div class="bartrack">
      <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:var(--drill);width:${subV||0}%"></div>
      <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:var(--text-muted);width:${univV||0}%"></div>
    </div>
    <div class="barval">${subV!==null?subV.toFixed(0)+'%':'n/a'} / ${univV!==null?univV.toFixed(0)+'%':'n/a'}</div>`;
  return row;
}

function renderDrilldownPanel() {
  const el = document.getElementById('drilldownArea');
  el.innerHTML = '';
  if (!drilldownState) return;
  const { subRows, universeRows, label } = drilldownState;

  const panel = document.createElement('div'); panel.className = 'panel';
  const head = document.createElement('div'); head.className = 'drillhead';
  head.innerHTML = `<div><h3 style="margin:0 0 3px;">Demographic profile: ${label}</h3><p class="desc" style="margin:0;">n = ${subRows.length}, out of ${universeRows.length} in the current view.</p></div>`;
  const closeBtn = document.createElement('div');
  closeBtn.className = 'drillclose';
  closeBtn.textContent = '\u2715 Close';
  closeBtn.onclick = clearDrilldown;
  head.appendChild(closeBtn);
  panel.appendChild(head);

  const legend = document.createElement('div'); legend.className = 'drilllegend';
  legend.innerHTML = `<span><i style="background:var(--drill)"></i>Selected (${label})</span><span><i style="background:var(--text-muted)"></i>Everyone in the current view</span>`;
  panel.appendChild(legend);

  const countryDim = document.createElement('div'); countryDim.className = 'drilldim';
  countryDim.innerHTML = '<h4>Country</h4>';
  const subC = catDist(subRows, 'country'), univC = catDist(universeRows, 'country');
  Object.keys(DRILL_COUNTRY_NAMES).sort((a,b) => (subC.dist[b]||0)-(subC.dist[a]||0)).forEach(c => {
    countryDim.appendChild(drillCatRow('Country', subC, univC, c, DRILL_COUNTRY_NAMES));
  });
  panel.appendChild(countryDim);

  const ageDim = document.createElement('div'); ageDim.className = 'drilldim';
  ageDim.innerHTML = '<h4>Age</h4>';
  const subA = catDist(subRows, 'age'), univA = catDist(universeRows, 'age');
  ['18-24','25-34','35-44','45-54'].forEach(c => ageDim.appendChild(drillCatRow('Age', subA, univA, c)));
  panel.appendChild(ageDim);

  const genderDim = document.createElement('div'); genderDim.className = 'drilldim';
  genderDim.innerHTML = '<h4>Gender</h4>';
  const subG = catDist(subRows, 'gender'), univG = catDist(universeRows, 'gender');
  ['M','F'].forEach(c => genderDim.appendChild(drillCatRow('Gender', subG, univG, c, DRILL_GENDER_NAMES)));
  panel.appendChild(genderDim);

  const incomeDim = document.createElement('div'); incomeDim.className = 'drilldim';
  incomeDim.innerHTML = '<h4>Household income (within market)</h4>';
  const subI = catDist(subRows, 'income'), univI = catDist(universeRows, 'income');
  ['L','M','H'].forEach(c => incomeDim.appendChild(drillCatRow('Income', subI, univI, c, DRILL_INCOME_NAMES)));
  panel.appendChild(incomeDim);

  const profileDim = document.createElement('div'); profileDim.className = 'drilldim';
  profileDim.innerHTML = '<h4>Profile</h4>';
  profileDim.appendChild(drillFlagRow('Any personal connection to Vietnam', subRows, universeRows, 'conn'));
  profileDim.appendChild(drillFlagRow('Vietnam origin (born/family)', subRows, universeRows, 'origin'));
  profileDim.appendChild(drillFlagRow('Influencer profile (F1)', subRows, universeRows, 'infl'));
  profileDim.appendChild(drillFlagRow('Aware of Vietnam Today', subRows, universeRows, 'vaware'));
  profileDim.appendChild(drillFlagRow('Has watched Vietnam Today', subRows, universeRows, 'vviewer'));
  panel.appendChild(profileDim);

  el.appendChild(panel);
}

function makeClickable(rowEl, universeRows, predicateFn, label) {
  if (!universeRows || typeof predicateFn !== 'function') return;
  rowEl.classList.add('clickable');
  rowEl.onclick = () => {
    const subRows = universeRows.filter(predicateFn);
    showDrilldown(subRows, universeRows, label);
  };
}

// ---------------- UI BUILD ----------------
function buildNav() {
  const el = document.getElementById('navList');
  el.innerHTML = '';
  Object.keys(SECTIONS).forEach(key => {
    const item = document.createElement('div');
    item.className = 'navitem' + (key===currentSection ? ' active':'');
    const icon = SECTIONS[key].icon || '';
    item.innerHTML = `<span class="navicon">${icon}</span><span>${SECTIONS[key].label}</span>`;
    item.onclick = () => { currentSection = key; currentModule = Object.keys(SECTIONS[key].modules)[0]; render(); };
    el.appendChild(item);
  });
}

function buildFilterPanel(containerId, state, cardClass) {
  const el = document.getElementById(containerId);
  el.innerHTML = '';
  FILTER_DEFS.forEach(f => {
    const grp = document.createElement('div');
    grp.className = 'filtergroup';
    const lbl = document.createElement('label');
    lbl.className = 'flabel';
    lbl.textContent = f.label;
    grp.appendChild(lbl);
    if (f.type === 'multi') {
      const cs = document.createElement('div'); cs.className='chipset';
      if (f.exclusiveTotal) {
        const totalChip = document.createElement('div');
        totalChip.className = 'chip' + (state[f.key].length===0 ? ' sel':'');
        totalChip.textContent = 'Total';
        totalChip.onclick = () => { state[f.key] = []; render(); };
        cs.appendChild(totalChip);
      }
      f.options.forEach(opt => {
        const chip = document.createElement('div');
        chip.className = 'chip' + (state[f.key].includes(opt) ? ' sel':'');
        chip.textContent = (f.names && f.names[opt]) || opt;
        chip.onclick = () => {
          const idx = state[f.key].indexOf(opt);
          if (idx>=0) state[f.key].splice(idx,1); else state[f.key].push(opt);
          render();
        };
        cs.appendChild(chip);
      });
      grp.appendChild(cs);
    } else {
      const ts = document.createElement('div'); ts.className='triset';
      [['any','Any'],['yes','Yes'],['no','No']].forEach(([v,l]) => {
        const t = document.createElement('div');
        t.className = 'tri' + (state[f.key]===v ? ' sel':'');
        t.textContent = l;
        t.onclick = () => { state[f.key] = v; render(); };
        ts.appendChild(t);
      });
      grp.appendChild(ts);
    }
    el.appendChild(grp);
  });
}

function baseNFlag(rows, field) {
  let n = 0;
  rows.forEach(r => { const v = val(r,field); if (v===1||v===0) n++; });
  return n;
}

function renderFlagsModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const data = mod.fields.map(([field,label]) => ({
    field, label, a: pctFlag(rowsA, field), b: compareOn ? pctFlag(rowsB, field) : null,
  }));
  data.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span class="vA">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</span> / <span class="vB">${d.b!==null?d.b.toFixed(0)+'%':'n/a'}</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</div>`;
      makeClickable(row, rowsA, r => val(r, d.field) === 1, d.label);
    }
    vizArea.appendChild(row);
  });
  const baseA = baseNFlag(rowsA, mod.fields[0][0]);
  const baseB = compareOn ? baseNFlag(rowsB, mod.fields[0][0]) : null;
  document.getElementById('panelFootnote').textContent = compareOn
    ? `Base | Audience A: ${baseA}  ·  Audience B: ${baseB}`
    : `Base: ${baseA}${baseA < 100 ? ' (small base, read as directional)' : ''}`;
}

function renderCategoricalModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const labels = CAT_LABELS[mod.field] || {};
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;
  const cats = Object.keys(labels).filter(c => distA.dist[c]!==undefined || (distB && distB.dist[c]!==undefined));
  Object.keys(distA.dist).forEach(c => { if (!cats.includes(c)) cats.push(c); });
  const data = cats.map(c => ({ cat:c, label: labels[c]||c, a: distA.dist[c]||0, b: distB?(distB.dist[c]||0):null }));
  data.sort((x,y) => y.a-x.a);
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span class="vA">${d.a.toFixed(0)}%</span> / <span class="vB">${d.b.toFixed(0)}%</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a.toFixed(0)}%</div>`;
      makeClickable(row, rowsA, r => val(r, mod.field) === d.cat, d.label);
    }
    vizArea.appendChild(row);
  });
  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '');
}

const SENTIMENT_GROUPS = [
  { key:'pos', label:'Positive', cats:['pos_mostly','pos_more'] },
  { key:'neu', label:'Neutral (positive and negative equally)', cats:['neutral'] },
  { key:'neg', label:'Negative', cats:['neg_more','neg_mostly'] },
];

function renderSentimentModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  function grouped(dist) {
    const g = {};
    SENTIMENT_GROUPS.forEach(grp => { g[grp.key] = grp.cats.reduce((s,c) => s + (dist.dist[c]||0), 0); });
    return g;
  }
  const gA = grouped(distA);
  const gB = distB ? grouped(distB) : null;
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view

  // Net score summary card FIRST, above the bars
  const nssA = Math.round((gA.pos - gA.neg) * 10) / 10;
  const nssB = gB ? Math.round((gB.pos - gB.neg) * 10) / 10 : null;
  const nssWrap = document.createElement('div');
  nssWrap.className = 'kpi-grid';
  nssWrap.style.marginBottom = '16px';
  nssWrap.innerHTML = `
    <div class="kpi">
      <div class="kval" style="color:${nssA>=0?'var(--posB)':'var(--negB)'};">${nssA>=0?'+':''}${nssA.toFixed(0)}</div>
      <div class="klabel">Net sentiment score${compareOn?', Audience A':''} (% positive minus % negative)</div>
    </div>
    ${compareOn ? `<div class="kpi">
      <div class="kval" style="color:${nssB>=0?'var(--posB)':'var(--negB)'};">${nssB>=0?'+':''}${nssB.toFixed(0)}</div>
      <div class="klabel">Net sentiment score, Audience B (% positive minus % negative)</div>
    </div>` : ''}
  `;
  vizArea.appendChild(nssWrap);

  const colorFor = { pos: ['var(--posA)','var(--posB)'], neu: ['var(--neuA)','var(--neuB)'], neg: ['var(--negA)','var(--negB)'] };
  SENTIMENT_GROUPS.forEach(grp => {
    const row = document.createElement('div'); row.className='barrow';
    const a = gA[grp.key], b = gB ? gB[grp.key] : null;
    const [cA, cB] = colorFor[grp.key];
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${grp.label}</div>
        <div class="bartrack">
          <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:${cA};width:${(a/maxV*100).toFixed(1)}%"></div>
          <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:${cB};width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span style="color:${cA}">${a.toFixed(0)}%</span> / <span style="color:${cB}">${b.toFixed(0)}%</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${grp.label}</div>
        <div class="bartrack"><div style="background:${cA};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, rowsA, r => grp.cats.includes(val(r, mod.field)), grp.label);
    }
    vizArea.appendChild(row);
  });

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '') + `. Positive combines "mostly positive" and "more positive than negative"; negative combines "more negative than positive" and "mostly negative".`;
}

const SCALEBAR_META = {
  c15: {
    order: ['def_would','prob_would','notsure','prob_not','def_not'],
    labels: { def_would:'Definitely would', prob_would:'Probably would', notsure:'Not sure', prob_not:'Probably not', def_not:'Definitely not' },
    top2: ['def_would','prob_would'], bottom2: ['prob_not','def_not'],
    topLabel: 'Would watch (top 2 box)', bottomLabel: 'Would not watch (bottom 2 box)', netLabel: 'Net intent to watch',
  },
};

function renderScaleBarModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const meta = SCALEBAR_META[mod.field];
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  const n = meta.order.length;
  // 5-step diverging color per position (index 0..n-1), blue -> gray -> red
  const stopsA = ['var(--posB)','var(--posA)','var(--neuA)','var(--negA)','var(--negB)'];
  const stopsB = ['var(--posB)','var(--posA)','var(--neuB)','var(--negA)','var(--negB)'];

  const wrap = document.createElement('div');
  wrap.className = 'scalewrap';

  const barsCol = document.createElement('div');
  barsCol.className = 'scalebars';
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  meta.order.forEach((k,i) => {
    const a = distA.dist[k]||0, b = distB ? (distB.dist[k]||0) : null;
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${meta.labels[k]}</div>
        <div class="bartrack">
          <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:${stopsA[i]};width:${(a/maxV*100).toFixed(1)}%"></div>
          <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:${stopsB[i]};width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span style="color:${stopsA[i]}">${a.toFixed(0)}%</span> / <span style="color:${stopsB[i]}">${b.toFixed(0)}%</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${meta.labels[k]}</div>
        <div class="bartrack"><div style="background:${stopsA[i]};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, rowsA, r => val(r, mod.field) === k, meta.labels[k]);
    }
    barsCol.appendChild(row);
  });
  wrap.appendChild(barsCol);

  function sumCats(dist, cats) { return cats.reduce((s,c) => s + (dist.dist[c]||0), 0); }
  const topA = sumCats(distA, meta.top2), botA = sumCats(distA, meta.bottom2), netA = Math.round((topA-botA)*10)/10;
  const topB = distB ? sumCats(distB, meta.top2) : null;
  const botB = distB ? sumCats(distB, meta.bottom2) : null;
  const netB = distB!==null && topB!==null ? Math.round((topB-botB)*10)/10 : null;

  const sqCol = document.createElement('div');
  sqCol.className = 'sqcol';

  const posTile = document.createElement('div');
  posTile.className = 'sqtile pos';
  posTile.innerHTML = `<div class="sqval" style="color:var(--posB)">${topA.toFixed(0)}%</div>
    ${compareOn ? `<div class="sqvalB" style="color:var(--posB)">B: ${topB.toFixed(0)}%</div>` : ''}
    <div class="sqlabel">${meta.topLabel}</div>`;
  sqCol.appendChild(posTile);

  const netTile = document.createElement('div');
  netTile.className = 'sqtile net';
  netTile.innerHTML = `<div class="sqval" style="color:${netA>=0?'var(--posB)':'var(--negB)'}">${netA>=0?'+':''}${netA.toFixed(0)}</div>
    ${compareOn ? `<div class="sqvalB" style="color:${netB>=0?'var(--posB)':'var(--negB)'}">B: ${netB>=0?'+':''}${netB.toFixed(0)}</div>` : ''}
    <div class="sqlabel">${meta.netLabel}</div>`;
  sqCol.appendChild(netTile);

  const negTile = document.createElement('div');
  negTile.className = 'sqtile neg';
  negTile.innerHTML = `<div class="sqval" style="color:var(--negB)">${botA.toFixed(0)}%</div>
    ${compareOn ? `<div class="sqvalB" style="color:var(--negB)">B: ${botB.toFixed(0)}%</div>` : ''}
    <div class="sqlabel">${meta.bottomLabel}</div>`;
  sqCol.appendChild(negTile);

  wrap.appendChild(sqCol);

  if (!compareOn) {
    makeClickable(posTile, rowsA, r => meta.top2.includes(val(r, mod.field)), meta.topLabel);
    makeClickable(negTile, rowsA, r => meta.bottom2.includes(val(r, mod.field)), meta.bottomLabel);
  }

  vizArea.appendChild(wrap);
  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '');
}

const RECALL_ORDER = ['several','once','dontremember','no'];
const RECALL_LABELS = { several:'Yes, several times', once:'Yes, once or twice', dontremember:'I don\u2019t remember', no:'No' };
const RECALL_COLORS_A = { several:'var(--posB)', once:'var(--posA)', dontremember:'var(--neuA)', no:'var(--negA)' };
const RECALL_COLORS_B = { several:'var(--posB)', once:'var(--posA)', dontremember:'var(--neuB)', no:'var(--negB)' };

function npsStats(rows, field) {
  const vals = rows.map(r => val(r,field)).filter(v => v!==null && v!==undefined);
  const n = vals.length;
  if (n===0) return { n:0, avg:null, promoters:null, passives:null, detractors:null, nps:null };
  const avg = vals.reduce((s,v)=>s+v,0)/n;
  const promoters = vals.filter(v=>v>=9).length/n*100;
  const passives = vals.filter(v=>v>=7 && v<=8).length/n*100;
  const detractors = vals.filter(v=>v<=6).length/n*100;
  return { n, avg: Math.round(avg*10)/10, promoters: Math.round(promoters*10)/10, passives: Math.round(passives*10)/10, detractors: Math.round(detractors*10)/10, nps: Math.round((promoters-detractors)*10)/10 };
}

function renderNPSModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const sA = npsStats(rowsA, mod.field);
  const sB = compareOn ? npsStats(rowsB, mod.field) : null;

  const summary = document.createElement('div');
  summary.className = 'kpi-grid';
  summary.style.marginBottom = '16px';
  summary.innerHTML = `
    <div class="kpi">
      <div class="kval">${sA.avg!==null?sA.avg.toFixed(1):'n/a'}</div>
      <div class="klabel">Average score, 0 to 10${compareOn?', Audience A':''}</div>
      ${compareOn ? `<div class="kvalB">B: ${sB.avg!==null?sB.avg.toFixed(1):'n/a'}</div>` : ''}
    </div>
    <div class="kpi">
      <div class="kval" style="color:${sA.nps!==null && sA.nps>=0?'var(--posB)':'var(--negB)'};">${sA.nps!==null?(sA.nps>=0?'+':'')+sA.nps.toFixed(0):'n/a'}</div>
      <div class="klabel">Net recommendation score (promoters minus detractors)</div>
      ${compareOn ? `<div class="kvalB">B: ${sB.nps!==null?(sB.nps>=0?'+':'')+sB.nps.toFixed(0):'n/a'}</div>` : ''}
    </div>
  `;
  vizArea.appendChild(summary);

  const bands = [
    { label:'Promoters (9\u201310)', a:sA.promoters, b:sB?sB.promoters:null, color:'var(--posB)', test:v=>v>=9 },
    { label:'Passives (7\u20138)', a:sA.passives, b:sB?sB.passives:null, color:'var(--neuA)', test:v=>v>=7&&v<=8 },
    { label:'Detractors (0\u20136)', a:sA.detractors, b:sB?sB.detractors:null, color:'var(--negB)', test:v=>v<=6 },
  ];
  bands.forEach(band => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${band.label}</div>
        <div class="bartrack">
          <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:${band.color};width:${(band.a||0)}%"></div>
          <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:${band.color};opacity:.6;width:${(band.b||0)}%"></div>
        </div>
        <div class="barval">${band.a!==null?band.a.toFixed(0)+'%':'n/a'} / ${band.b!==null?band.b.toFixed(0)+'%':'n/a'}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${band.label}</div>
        <div class="bartrack"><div style="background:${band.color};height:100%;border-radius:4px;width:${(band.a||0)}%"></div></div>
        <div class="barval">${band.a!==null?band.a.toFixed(0)+'%':'n/a'}</div>`;
      makeClickable(row, rowsA, r => { const v = val(r, mod.field); return v!==null && v!==undefined && band.test(v); }, band.label);
    }
    vizArea.appendChild(row);
  });

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${sA.n}` + (compareOn ? `  ·  Audience B: ${sB.n}` : '') + `. Asked only of people who watch Vietnam Today.`;
}

function renderRecallModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  const yesA = (distA.dist.once||0) + (distA.dist.several||0);
  const yesB = distB ? (distB.dist.once||0) + (distB.dist.several||0) : null;

  const summary = document.createElement('div');
  summary.className = 'kpi-grid';
  summary.style.marginBottom = '16px';
  summary.innerHTML = `
    <div class="kpi">
      <div class="kval" style="color:var(--posB);">${yesA.toFixed(0)}%</div>
      <div class="klabel">Recalled Vietnam news${compareOn?', Audience A':''} (Yes, once or more, net share of voice)</div>
    </div>
    ${compareOn ? `<div class="kpi">
      <div class="kval" style="color:var(--posB);">${yesB.toFixed(0)}%</div>
      <div class="klabel">Recalled Vietnam news, Audience B (Yes, once or more, net share of voice)</div>
    </div>` : ''}
  `;
  vizArea.appendChild(summary);

  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  RECALL_ORDER.forEach(k => {
    const a = distA.dist[k]||0, b = distB ? (distB.dist[k]||0) : null;
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${RECALL_LABELS[k]}</div>
        <div class="bartrack">
          <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:${RECALL_COLORS_A[k]};width:${(a/maxV*100).toFixed(1)}%"></div>
          <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:${RECALL_COLORS_B[k]};width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span style="color:${RECALL_COLORS_A[k]}">${a.toFixed(0)}%</span> / <span style="color:${RECALL_COLORS_B[k]}">${b.toFixed(0)}%</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${RECALL_LABELS[k]}</div>
        <div class="bartrack"><div style="background:${RECALL_COLORS_A[k]};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, rowsA, r => val(r, mod.field) === k, RECALL_LABELS[k]);
    }
    vizArea.appendChild(row);
  });

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '') + `. "Yes, once or more" combines "yes, once or twice" and "yes, several times".`;
}

const SCALE5_ORDER = ['vi','i','si','sli','na'];
const SCALE5_LABELS = { vi:'Very interested', i:'Interested', si:'Somewhat interested', sli:'Slightly interested', na:'Not at all interested' };
const SCALE5_COLORS = { vi:'var(--posB)', i:'var(--posA)', si:'var(--neuA)', sli:'#E0A08F', na:'var(--negB)' };

function renderFullScaleModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');

  const legend = document.createElement('div');
  legend.className = 'scalelegend';
  legend.innerHTML = SCALE5_ORDER.map(k => `<span><i style="background:${SCALE5_COLORS[k]}"></i>${SCALE5_LABELS[k]}</span>`).join('');
  vizArea.appendChild(legend);

  function distFor(rows, field) {
    const d = catDist(rows, field);
    const out = {};
    SCALE5_ORDER.forEach(k => { out[k] = d.dist[k] || 0; });
    out._n = d.n;
    return out;
  }

  function stackTrack(dist, extraClass, clickCtx) {
    const track = document.createElement('div');
    track.className = 'stacktrack' + (extraClass ? ' '+extraClass : '');
    SCALE5_ORDER.forEach(k => {
      const seg = document.createElement('div');
      seg.className = 'stackseg';
      const w = dist[k];
      seg.style.width = w.toFixed(1) + '%';
      seg.style.background = SCALE5_COLORS[k];
      if (w >= 7) seg.textContent = w.toFixed(0) + '%';
      if (clickCtx) {
        seg.style.cursor = 'pointer';
        seg.onclick = () => {
          const subRows = clickCtx.universeRows.filter(r => val(r, clickCtx.field) === k);
          showDrilldown(subRows, clickCtx.universeRows, `${clickCtx.itemLabel}: ${SCALE5_LABELS[k]}`);
        };
      }
      track.appendChild(seg);
    });
    return track;
  }

  // sort items by net (vi+i) of Audience A, descending
  const items = mod.fields.map(([field,label]) => {
    const dA = distFor(rowsA, field);
    return { field, label, dA };
  });
  items.sort((x,y) => (y.dA.vi+y.dA.i) - (x.dA.vi+x.dA.i));

  items.forEach(({field,label,dA}) => {
    const wrap = document.createElement('div');
    wrap.className = 'stackrow';
    const netA = (dA.vi+dA.i).toFixed(0);
    if (compareOn) {
      const dB = distFor(rowsB, field);
      const netB = (dB.vi+dB.i).toFixed(0);
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span><span style="color:var(--lineA)">A: ${netA}%</span> &nbsp; <span style="color:var(--lineB)">B: ${netB}%</span></span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA));
      wrap.appendChild(stackTrack(dB, 'compareb'));
    } else {
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span>${netA}% net</span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA, null, { field, universeRows: rowsA, itemLabel: label }));
    }
    vizArea.appendChild(wrap);
  });

  document.getElementById('panelFootnote').textContent = compareOn
    ? `Top bar = Audience A, bottom bar = Audience B, for each item. Base | Audience A: ${rowsA.length}  ·  Audience B: ${rowsB.length}.`
    : `Base: ${rowsA.length}.`;
}

function renderA2TopicsModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');

  const chipWrap = document.createElement('div');
  chipWrap.className = 'chipset';
  chipWrap.style.marginBottom = '16px';
  ['All'].concat(TOPCOUNTRY_OPTIONS).forEach(c => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (a2Country===c ? ' sel':'');
    chip.textContent = c === 'All' ? 'All (pooled)' : c;
    chip.onclick = () => { a2Country = c; render(); };
    chipWrap.appendChild(chip);
  });
  vizArea.appendChild(chipWrap);

  const subA = a2Country==='All' ? rowsA : rowsA.filter(r => val(r,'topcountry')===a2Country);
  const subB = compareOn ? (a2Country==='All' ? rowsB : rowsB.filter(r => val(r,'topcountry')===a2Country)) : null;

  const data = mod.fields.map(([field,label]) => ({
    field, label, a: pctFlag(subA, field), b: compareOn ? pctFlag(subB, field) : null,
  }));
  data.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span class="vA">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</span> / <span class="vB">${d.b!==null?d.b.toFixed(0)+'%':'n/a'}</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</div>`;
      makeClickable(row, subA, r => val(r, d.field) === 1, d.label);
    }
    vizArea.appendChild(row);
  });

  const baseA = baseNFlag(subA, mod.fields[0][0]);
  const baseB = compareOn ? baseNFlag(subB, mod.fields[0][0]) : null;
  const whoText = a2Country==='All' ? 'everyone, across all top-pick countries' : `people who picked ${a2Country} as their personal top country`;
  document.getElementById('panelFootnote').textContent = compareOn
    ? `Showing ${whoText}. Base | Audience A: ${baseA}  ·  Audience B: ${baseB}`
    : `Showing ${whoText}. Base: ${baseA}${baseA < 50 ? ' (small base, read as directional)' : ''}`;
}

function renderTopicsCompareModule(rowsA) {
  const vizArea = document.getElementById('vizArea');

  const chipWrap = document.createElement('div');
  chipWrap.className = 'chipset';
  chipWrap.style.marginBottom = '16px';
  TOPCOUNTRY_OPTIONS.forEach(c => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (topicsCompareCountry===c ? ' sel':'');
    chip.textContent = c;
    chip.onclick = () => { topicsCompareCountry = c; render(); };
    chipWrap.appendChild(chip);
  });
  vizArea.appendChild(chipWrap);

  const countryRows = rowsA.filter(r => val(r,'topcountry')===topicsCompareCountry);
  const data = TOPIC_PAIRS.map(([key,label]) => ({
    label,
    country: pctFlag(countryRows, 'a2_'+key),
    vietnam: pctFlag(rowsA, 'd3_'+key),
  }));
  data.sort((x,y) => (y.country||0)-(x.country||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view

  const legend = document.createElement('div');
  legend.className = 'linelegend';
  legend.style.marginBottom = '10px';
  legend.innerHTML = `<span><i style="background:var(--lineB)"></i>${topicsCompareCountry}</span><span><i style="background:var(--lineA)"></i>Vietnam</span>`;
  vizArea.appendChild(legend);

  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    row.innerHTML = `<div class="barlabel">${d.label}</div>
      <div class="bartrack">
        <div class="barfillA" style="width:${(d.vietnam/maxV*100).toFixed(1)}%"></div>
        <div class="barfillB" style="width:${(d.country/maxV*100).toFixed(1)}%"></div>
      </div>
      <div class="barval"><span class="vB">${d.country!==null?d.country.toFixed(0)+'%':'n/a'}</span> / <span class="vA">${d.vietnam!==null?d.vietnam.toFixed(0)+'%':'n/a'}</span></div>`;
    vizArea.appendChild(row);
  });

  const baseCountry = baseNFlag(countryRows, 'a2_food');
  const baseVietnam = baseNFlag(rowsA, 'd3_food');
  document.getElementById('panelFootnote').textContent = `${topicsCompareCountry} is based only on people within the current filters who picked it as their personal top country (n=${baseCountry}). Vietnam is based on everyone within the current filters, since it was asked of all respondents (n=${baseVietnam}).`;
}

function renderCurveModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const W=880,H=320,padL=44,padR=20,padT=18,padB=34;
  const innerW=W-padL-padR, innerH=H-padT-padB;
  const n = mod.fields.length;
  const seriesA = mod.fields.map(([f]) => pctFlag(rowsA,f));
  const seriesB = compareOn ? mod.fields.map(([f]) => pctFlag(rowsB,f)) : null;
  const allV = seriesA.concat(seriesB||[]).filter(v=>v!==null);
  const maxV = Math.max(...allV, 5) * 1.15;
  function x(i){ return padL + innerW*i/(n-1); }
  function y(v){ return padT + innerH*(1 - v/maxV); }
  let svg = `<svg viewBox="0 0 ${W} ${H}" style="width:100%; max-width:${W}px; height:auto;">`;
  for (let g=0; g<=4; g++) {
    const v = maxV*g/4, gy = y(v);
    svg += `<line x1="${padL}" y1="${gy}" x2="${W-padR}" y2="${gy}" stroke="var(--border)" stroke-width="1"/>`;
    svg += `<text x="${padL-8}" y="${gy+4}" font-size="10" fill="var(--text-muted)" text-anchor="end">${v.toFixed(0)}%</text>`;
  }
  mod.fields.forEach(([f,lbl],i) => { svg += `<text x="${x(i)}" y="${H-padB+18}" font-size="9.5" fill="var(--text-secondary)" text-anchor="middle">${lbl}</text>`; });
  function drawLine(series,color) {
    let pts = series.map((v,i)=> v!==null?`${x(i)},${y(v)}`:null).filter(Boolean).join(' ');
    svg += `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`;
    series.forEach((v,i)=>{ if(v!==null) svg += `<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${color}"/>`; });
  }
  drawLine(seriesA,'var(--lineA)');
  if (seriesB) drawLine(seriesB,'var(--lineB)');
  svg += `</svg>`;
  const legend = document.createElement('div'); legend.className='linelegend';
  legend.innerHTML = `<span><i style="background:var(--lineA)"></i>Audience A</span>` + (compareOn ? `<span><i style="background:var(--lineB)"></i>Audience B</span>` : '');
  vizArea.appendChild(legend);
  const wrap = document.createElement('div'); wrap.innerHTML = svg; vizArea.appendChild(wrap);

  const noneA = pctFlag(rowsA, mod.noneField);
  const noneB = compareOn ? pctFlag(rowsB, mod.noneField) : null;
  document.getElementById('panelFootnote').textContent = `${mod.noneLabel} | Audience A: ${noneA!==null?noneA.toFixed(0)+'%':'n/a'}` + (compareOn?`  ·  Audience B: ${noneB!==null?noneB.toFixed(0)+'%':'n/a'}`:'');
}

function recallYesPct(rows) {
  const d = catDist(rows, 'recall');
  return d.n > 0 ? (d.dist.once||0) + (d.dist.several||0) : null;
}
function sentimentTop2Pct(rows) {
  const d = catDist(rows, 'sentiment');
  return d.n > 0 ? (d.dist.pos_mostly||0) + (d.dist.pos_more||0) : null;
}
function sentimentBottom2Pct(rows) {
  const d = catDist(rows, 'sentiment');
  return d.n > 0 ? (d.dist.neg_more||0) + (d.dist.neg_mostly||0) : null;
}
function sentimentNetScore(rows) {
  const pos = sentimentTop2Pct(rows), neg = sentimentBottom2Pct(rows);
  return (pos===null || neg===null) ? null : Math.round((pos-neg)*10)/10;
}

function renderKPIs(rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const kpis = [
    { label:'Aware of Vietnam Today', field:'vaware' },
    { label:'Has watched Vietnam Today', field:'vviewer' },
    { label:'Watched within past week', field:'vrecent' },
    { label:'Exposed to Vietnam info/news (past month)', compute:recallYesPct },
    { label:'Vietnam news sentiment | positive (top 2 box)', compute:sentimentTop2Pct, polarity:'pos', predicate:r=>['pos_mostly','pos_more'].includes(val(r,'sentiment')) },
    { label:'Vietnam news sentiment | net score', compute:sentimentNetScore, isScore:true },
    { label:'Vietnam news sentiment | negative (bottom 2 box)', compute:sentimentBottom2Pct, polarity:'neg', predicate:r=>['neg_more','neg_mostly'].includes(val(r,'sentiment')) },
    { label:'Any personal connection to Vietnam', field:'conn' },
    { label:'Vietnam origin (born/family)', field:'origin' },
    { label:'Influencer profile (F1)', field:'infl' },
    { label:'Net interest in Vietnam (A1)', field:'a1_vietnam' },
    { label:'Net interest in Southeast Asia', field:'r_sea' },
  ];
  const grid = document.createElement('div'); grid.className='kpi-grid';
  function fmt(v, k) {
    if (v === null) return 'n/a';
    if (k.isScore) return (v>=0?'+':'') + v.toFixed(0);
    return v.toFixed(0) + '%';
  }
  kpis.forEach(k => {
    const a = k.compute ? k.compute(rowsA) : pctFlag(rowsA, k.field);
    const div = document.createElement('div'); div.className='kpi';
    let colorOverride = '';
    if (k.polarity) colorOverride = `style="color:var(--${k.polarity === 'pos' ? 'posB' : 'negB'});"`;
    else if (k.isScore && a !== null) colorOverride = `style="color:var(--${a>=0?'posB':'negB'});"`;
    div.innerHTML = `<div class="kval" ${colorOverride}>${fmt(a,k)}</div><div class="klabel">${k.label}</div>` + (compareOn ? `<div class="kvalB">B: ${(()=>{const b=k.compute ? k.compute(rowsB) : pctFlag(rowsB,k.field);return fmt(b,k);})()}</div>` : '');
    if (!compareOn && k.predicate) makeClickable(div, rowsA, k.predicate, k.label);
    grid.appendChild(div);
  });
  vizArea.appendChild(grid);
  document.getElementById('panelFootnote').textContent = 'Vietnam news sentiment is based only on people who recalled seeing something (a smaller base than the full audience).';
}

function realCountryN(countryCode) {
  return countryCode === 'TOTAL' ? ROWS.length : ROWS.filter(r => val(r,'country')===countryCode).length;
}

function renderScreenerTargetPanel(suffix, target) {
  const wrap = document.getElementById('screenerChips_' + suffix);
  wrap.innerHTML = '';
  SCREENER.order.forEach(code => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (target.country===code ? ' sel':'');
    chip.textContent = SCREENER.names[code];
    chip.onclick = () => { target.country = code; render(); };
    wrap.appendChild(chip);
  });
  if (target.base === 'all') {
    const n = SCREENER.base_n[target.country];
    document.getElementById('screenerN_' + suffix).textContent = n ? `n = ${n.total} responses, ${n.complete} completes` : '';
  } else {
    const realN = realCountryN(target.country);
    document.getElementById('screenerN_' + suffix).textContent = `n = ${realN} completed interviews (final data)`;
  }

  const bt = document.getElementById('screenerBaseToggle_' + suffix);
  bt.innerHTML = '';
  [['all', `All respondents (${SCREENER.base_n.TOTAL.total.toLocaleString()})`], ['completes', `Completed interviews only (${ROWS.length.toLocaleString()})`]].forEach(([v,l]) => {
    const t = document.createElement('div');
    t.className = 'tri' + (target.base===v ? ' sel':'');
    t.textContent = l;
    t.onclick = () => { target.base = v; render(); };
    bt.appendChild(t);
  });
}

function pctFlagCountry(field, countryCode) {
  const rows = countryCode==='TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===countryCode);
  return pctFlag(rows, field);
}

function screenerTargetLabel(target) {
  return `${SCREENER.names[target.country]} · ${target.base==='all' ? 'all respondents' : 'completes only'}`;
}

function screenerValue(mod, target, itemLabel) {
  if (target.base === 'all') {
    const data = SCREENER[mod.dataKey];
    return data[itemLabel][target.country];
  }
  return pctFlagCountry(mod.fieldMap[itemLabel], target.country);
}

function screenerFullScaleFor(field, dataKey, target) {
  if (target.base === 'all') {
    const shortname = field.replace(/^r_/, '').replace(/^a1_/, '');
    const scaleObj = dataKey === 'S8' ? SCREENER.S8_scale[shortname] : SCREENER.A1_scale[shortname];
    const d = scaleObj ? scaleObj[target.country] : null;
    const out = {};
    SCALE5_ORDER.forEach(k => { out[k] = (d && d[k]!==null && d[k]!==undefined) ? d[k] : 0; });
    return out;
  }
  const scaleField = field + '_scale';
  const rows = target.country === 'TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===target.country);
  const dist = catDist(rows, scaleField);
  const out = {};
  SCALE5_ORDER.forEach(k => { out[k] = dist.dist[k] || 0; });
  return out;
}

function renderScreenerFullScale(mod) {
  const vizArea = document.getElementById('vizArea');
  const legend = document.createElement('div');
  legend.className = 'scalelegend';
  legend.innerHTML = SCALE5_ORDER.map(k => `<span><i style="background:${SCALE5_COLORS[k]}"></i>${SCALE5_LABELS[k]}</span>`).join('');
  vizArea.appendChild(legend);

  function stackTrack(dist, extraClass) {
    const track = document.createElement('div');
    track.className = 'stacktrack' + (extraClass ? ' '+extraClass : '');
    SCALE5_ORDER.forEach(k => {
      const seg = document.createElement('div');
      seg.className = 'stackseg';
      const w = dist[k];
      seg.style.width = w.toFixed(1) + '%';
      seg.style.background = SCALE5_COLORS[k];
      if (w >= 7) seg.textContent = w.toFixed(0) + '%';
      track.appendChild(seg);
    });
    return track;
  }

  const items = Object.keys(mod.fieldMap).map(label => {
    const field = mod.fieldMap[label];
    const dA = screenerFullScaleFor(field, mod.dataKey, screenerTargetA);
    return { label, dA };
  });
  items.sort((x,y) => (y.dA.vi+y.dA.i) - (x.dA.vi+x.dA.i));

  items.forEach(({label,dA}) => {
    const field = mod.fieldMap[label];
    const wrap = document.createElement('div');
    wrap.className = 'stackrow';
    const netA = (dA.vi+dA.i).toFixed(0);
    if (screenerCompareOn) {
      const dB = screenerFullScaleFor(field, mod.dataKey, screenerTargetB);
      const netB = (dB.vi+dB.i).toFixed(0);
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span><span style="color:var(--lineA)">A: ${netA}%</span> &nbsp; <span style="color:var(--lineB)">B: ${netB}%</span></span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA));
      wrap.appendChild(stackTrack(dB, 'compareb'));
    } else {
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span>${netA}% net</span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA));
    }
    vizArea.appendChild(wrap);
  });

  document.getElementById('panelFootnote').textContent = screenerCompareOn
    ? `Target A: ${screenerTargetLabel(screenerTargetA)}  ·  Target B: ${screenerTargetLabel(screenerTargetB)}`
    : `Base | ${screenerTargetLabel(screenerTargetA)}.`;
}

function renderScreenerModule(mod) {
  const vizArea = document.getElementById('vizArea');
  if (mod.type === 'screenerfullscale') { renderScreenerFullScale(mod); return; }
  if (mod.type === 'funnel') {
    if (screenerCompareOn || screenerTargetA.base === 'completes') {
      const p = document.createElement('p');
      p.className = 'desc';
      p.textContent = 'This table only applies to a single "All respondents" target, since it shows how the screener funnelled down to completes. Turn off the second target and set Target A\u2019s base to "All respondents" to see it.';
      vizArea.appendChild(p);
      return;
    }
    const table = document.createElement('table');
    table.className = 'heat';
    let head = '<thead><tr><th class="rowhead">Market</th><th>Total responses</th><th>Final complete</th><th>Incidence %</th></tr></thead>';
    let body = '<tbody>';
    SCREENER.order.forEach(code => {
      const b = SCREENER.base_n[code];
      const pct = b ? (b.complete/b.total*100).toFixed(1) : 'n/a';
      body += `<tr><td class="rowhead">${SCREENER.names[code]}</td><td>${b.total}</td><td>${b.complete}</td><td>${pct}%</td></tr>`;
    });
    body += '</tbody>';
    table.innerHTML = head + body;
    vizArea.appendChild(table);
    return;
  }

  const itemLabels = mod.dataKey ? Object.keys(SCREENER[mod.dataKey]) : Object.keys(mod.fieldMap);
  let vals = itemLabels.map(item => ({
    label: item,
    a: screenerValue(mod, screenerTargetA, item),
    b: screenerCompareOn ? screenerValue(mod, screenerTargetB, item) : null,
  }));
  vals.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  vals.forEach(v => {
    const row = document.createElement('div'); row.className='barrow';
    if (screenerCompareOn) {
      row.innerHTML = `<div class="barlabel">${v.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(v.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(v.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><span class="vA">${v.a!==null?v.a.toFixed(0)+'%':'n/a'}</span> / <span class="vB">${v.b!==null?v.b.toFixed(0)+'%':'n/a'}</span></div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${v.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(v.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${v.a!==null&&v.a!==undefined?v.a.toFixed(1)+'%':'n/a'}</div>`;
      if (screenerTargetA.base === 'completes' && mod.fieldMap) {
        const field = mod.fieldMap[v.label];
        const universeRows = screenerTargetA.country === 'TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===screenerTargetA.country);
        makeClickable(row, universeRows, r => val(r, field) === 1, v.label);
      }
    }
    vizArea.appendChild(row);
  });
  document.getElementById('panelFootnote').textContent = screenerCompareOn
    ? `Target A: ${screenerTargetLabel(screenerTargetA)}  ·  Target B: ${screenerTargetLabel(screenerTargetB)}`
    : `Base | ${screenerTargetLabel(screenerTargetA)}.`;
}

function render() {
  document.getElementById('toggleBBtn').onclick = () => { compareOn = !compareOn; render(); };
  document.getElementById('screenerToggleBBtn').onclick = () => { screenerCompareOn = !screenerCompareOn; render(); };
  document.getElementById('resetA').onclick = () => { filterA = defaultFilterState(); render(); };
  document.getElementById('resetB').onclick = () => { filterB = defaultFilterState(); render(); };

  clearDrilldown();
  buildNav();
  const section = SECTIONS[currentSection];

  document.getElementById('filterbarWrap').style.display = section.isScreener ? 'none' : '';
  document.getElementById('toggleBWrap').style.display = section.isScreener ? 'none' : '';
  document.getElementById('screenerBar').style.display = section.isScreener ? '' : 'none';
  document.getElementById('screenerBarB').style.display = (section.isScreener && screenerCompareOn) ? '' : 'none';
  document.getElementById('screenerToggleBWrap').style.display = section.isScreener ? '' : 'none';

  let rowsA = [], rowsB = [];
  if (section.isScreener) {
    renderScreenerTargetPanel('A', screenerTargetA);
    if (screenerCompareOn) renderScreenerTargetPanel('B', screenerTargetB);
    document.getElementById('screenerToggleBBtn').className = 'toggleB' + (screenerCompareOn?' on':'');
    document.getElementById('screenerToggleBBtn').textContent = screenerCompareOn ? '✕ Remove second target' : '+ Compare with a second market or base';
    document.getElementById('totalN').textContent = ROWS.length;
  } else {
    buildFilterPanel('filtersA', filterA, 'A');
    document.getElementById('cardB').style.display = compareOn ? '' : 'none';
    if (compareOn) buildFilterPanel('filtersB', filterB, 'B');
    document.getElementById('toggleBBtn').className = 'toggleB' + (compareOn?' on':'');
    document.getElementById('toggleBBtn').textContent = compareOn ? '✕ Remove second audience' : '+ Compare with a second audience';

    rowsA = filteredRows(filterA);
    rowsB = compareOn ? filteredRows(filterB) : [];
    document.getElementById('ncountA').textContent = `n = ${rowsA.length}`;
    document.getElementById('ncountB').textContent = `n = ${rowsB.length}`;
    document.getElementById('totalN').textContent = ROWS.length;
  }

  document.getElementById('pageH2').textContent = section.label;
  document.getElementById('pageP').textContent = section.isScreener
    ? 'Switch the base below between everyone who took the screener and the quality-checked completes only, to see how screening and quotas shifted the picture.'
    : 'Set filters for one or two audiences below, then browse modules to compare them on any survey variable.';

  const modTabs = document.getElementById('moduleTabs');
  modTabs.innerHTML = '';
  Object.keys(section.modules).forEach(mk => {
    const tab = document.createElement('div');
    tab.className = 'mtab' + (mk===currentModule ? ' active':'');
    tab.textContent = section.modules[mk].label;
    tab.onclick = () => { currentModule = mk; render(); };
    modTabs.appendChild(tab);
  });

  const mod = section.modules[currentModule];
  document.getElementById('panelTitle').textContent = mod.label;
  document.getElementById('panelDesc').textContent = mod.desc || '';
  const vizArea = document.getElementById('vizArea');
  vizArea.innerHTML = '';
  document.getElementById('panelFootnote').textContent = '';

  if (section.isScreener) renderScreenerModule(mod);
  else if (mod.type === 'kpi') renderKPIs(rowsA, rowsB);
  else if (mod.type === 'flags') renderFlagsModule(mod, rowsA, rowsB);
  else if (mod.type === 'a2topics') renderA2TopicsModule(mod, rowsA, rowsB);
  else if (mod.type === 'categorical') renderCategoricalModule(mod, rowsA, rowsB);
  else if (mod.type === 'sentiment') renderSentimentModule(mod, rowsA, rowsB);
  else if (mod.type === 'scalebar') renderScaleBarModule(mod, rowsA, rowsB);
  else if (mod.type === 'recallbar') renderRecallModule(mod, rowsA, rowsB);
  else if (mod.type === 'nps') renderNPSModule(mod, rowsA, rowsB);
  else if (mod.type === 'fullscale') renderFullScaleModule(mod, rowsA, rowsB);
  else if (mod.type === 'topicscompare') renderTopicsCompareModule(rowsA);
  else if (mod.type === 'curve') renderCurveModule(mod, rowsA, rowsB);
}

export default render;